parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "primary_root_cause": {
      "type": "string"
    },
    "root_cause_category": {
      "type": "string",
      "enum": [
        "Application Bug",
        "Database Failure",
        "Network Issue",
        "Infrastructure Failure",
        "Cloud Configuration",
        "Authentication Failure",
        "Storage Failure",
        "Third-party Service",
        "Human Error",
        "Unknown"
      ]
    },
    "affected_component": {
      "type": "string"
    },
    "technical_explanation": {
      "type": "string"
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    }
  },
  "required": [
    "primary_root_cause",
    "root_cause_category",
    "affected_component",
    "technical_explanation",
    "confidence"
  ]
}

parameters.jsCode:
const j = $input.first().json;
let o = j.output ?? j;
if (typeof o === 'string') {
  try { o = JSON.parse(o); } catch (e) { throw new Error('Invalid agent JSON: ' + o); }
}
return [{ json: o }];
